#!/usr/bin/env python3
import json
import os
from datetime import datetime, date
from difflib import unified_diff
import re

# Configuration
CURRENT_DATE = date(2026, 8, 19)  # Current date for SSL expiry calculation
DAYS_BEFORE_CRITICAL = 30
DAYS_BEFORE_WARNING = 60
WORKSPACE_ROOT = "."  # Workspace root directory

def load_json_file(path):
    """Load a JSON file and return its contents."""
    try:
        with open(path, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        return None
    except json.JSONDecodeError:
        return None

def compare_configs(old_content, new_content):
    """Compare two config files and return differences."""
    old_lines = old_content.split('\n')
    new_lines = new_content.split('\n')

    differences = []

    # Simple line-by-line comparison for config diffs
    # Looking for key additions, removals, and changes
    old_dict = {}
    new_dict = {}

    # Parse first block (http)
    http_section = ""
    https_section_start = False
    https_section = ""

    for i, line in enumerate(old_lines):
        if 'server {' in line:
            continue
        if line.strip().startswith('#') and 'http' in line:
            if 'http' in old_lines[i-1]:
                http_section += line + "\n"
        elif line.strip().startswith('#'):
            break
        else:
            http_section += line + "\n"
        if i > 0 and 'ssl_certificate' in line:
            break

    http_lines = http_section.split('\n')

    # Parse first block (https) for old
    https_section_old = ""
    in_https_block = False
    for line in old_lines:
        if line.strip().startswith('#'):
            if in_https_block:
                break
            continue
        if 'server {' in line:
            continue
        if line.strip().startswith('#') and 'ssl' in line.lower():
            in_https_block = True
            continue
        https_section_old += line + "\n"

    # Parse first block (http) for new
    https_section_new = ""
    in_https_block = False
    for line in new_lines:
        if line.strip().startswith('#'):
            if in_https_block:
                break
            continue
        if 'server {' in line:
            continue
        if line.strip().startswith('#') and 'ssl' in line.lower():
            in_https_block = True
            continue
        https_section_new += line + "\n"

    # Compare the two sections
    diff = unified_diff(
        https_section_old.split('\n'),
        https_section_new.split('\n'),
        fromfile='old',
        tofile='new',
        lineterm=''
    )

    diff_text = '\n'.join(diff)
    return diff_text, https_section_old, https_section_new

def find_diff_sections(old_content, new_content):
    """Find specific differences between config sections."""
    differences = []

    # Find location blocks differences
    # Look for "location /" in new content
    if 'location /' in new_content:
        old_location = re.search(r'location \/ \{[^}]*try_files', old_content)
        new_location = re.search(r'location \/ \{[^}]*try_files', new_content)

        if old_location and new_location:
            old_content_section = old_location.group(0)
            new_content_section = new_location.group(0)

            if old_content_section != new_content_section:
                differences.append({
                    "type": "location_try_files",
                    "old": old_content_section,
                    "new": new_content_section,
                    "summary": "Laravel try_files routing pattern changed"
                })

    # Look for new location blocks
    if 'location /api/telegram/webhook' in new_content and 'location /api/telegram/webhook' not in old_content:
        # Extract the entire location block
        api_match = re.search(r'location /api/telegram/webhook \{(.*?)\n    \}\s*\n', new_content, re.DOTALL)
        if api_match:
            differences.append({
                "type": "api_location_added",
                "new": api_match.group(0),
                "summary": "New API location block for Telegram webhook added"
            })

    # Check for proxy settings changes
    if 'location /api/telegram/webhook' in new_content:
        proxy_config = re.search(r'proxy_pass (http://[\d.]+:\d+)\s*;', new_content)
        if proxy_config:
            differences.append({
                "type": "proxy_pass_added",
                "value": proxy_config.group(1),
                "summary": "Proxy configuration for Telegram webhook added"
            })

    return differences

def analyze_json_changes(old_json, new_json):
    """Analyze differences in JSON config files."""
    differences = []

    if old_json is None:
        return [{"type": "new_file", "value": new_json, "summary": "New configuration file created"}]

    # Compare top-level keys
    for key in new_json:
        if key not in old_json:
            differences.append({
                "type": "new_field",
                "field": key,
                "value": new_json[key],
                "summary": f"New '{key}' field added"
            })
        else:
            # Compare nested values
            old_val = old_json[key]
            new_val = new_json[key]

            if isinstance(old_val, dict) and isinstance(new_val, dict):
                for sub_key in new_val:
                    if sub_key not in old_val:
                        differences.append({
                            "type": "new_nested_field",
                            "field": f"{key}.{sub_key}",
                            "value": new_val[sub_key],
                            "summary": f"New nested field '{key}.{sub_key}' added"
                        })
                    elif old_val[sub_key] != new_val[sub_key]:
                        old_sub_val = old_val[sub_key]
                        differences.append({
                            "type": "changed_value",
                            "field": f"{key}.{sub_key}",
                            "old": old_sub_val,
                            "new": new_val[sub_key],
                            "summary": f"Changed value for '{sub_key}'"
                        })

    return differences

def scan_for_credentials(content, filename):
    """Scan config content for potential credential leaks."""
    credentials = []

    patterns = {
        "api_key": {
            "pattern": r'(?:api[_-]?key|apikey)\s*[=:]\s*["\']?([A-Za-z0-9_\-]+)["\']?',
            "severity": "high",
            "recommendation": "Use environment variables or secure vault instead"
        },
        "secret": {
            "pattern": r'(?:secret[_-]?key|secret)\s*[=:]\s*["\']?([A-Za-z0-9_\-]+)["\']?',
            "severity": "critical",
            "recommendation": "Remove from file, use environment variables"
        },
        "token": {
            "pattern": r'(?:access[_-]?token|token)\s*[=:]\s*["\']?([A-Za-z0-9_\-]+)["\']?',
            "severity": "critical",
            "recommendation": "Use environment variables or secure vault"
        },
        "password": {
            "pattern": r'(?:password|passwd|pwd)\s*[=:]\s*["\']?([A-Za-z0-9_\-]+)["\']?',
            "severity": "critical",
            "recommendation": "Use environment variables or secret manager"
        },
        "webhook_secret": {
            "pattern": r'(?:webhook[_-]?secret|secret)\s*[=:]\s*["\']?([A-Za-z0-9_\-]+)["\']?',
            "severity": "critical",
            "recommendation": "Generate real secret key and remove placeholder"
        },
        "db_password": {
            "pattern": r'(?:database[_-]?password|db_password|MYSQL_PASSWORD|PG_PASSWORD)[\s:=]+["\']?([A-Za-z0-9_\-]+)["\']?',
            "severity": "critical",
            "recommendation": "Use .env file or environment variables"
        },
        "bearer": {
            "pattern": r'bearer?\s+([A-Za-z0-9_\-]+)',
            "severity": "critical",
            "recommendation": "Remove bearer token from config"
        }
    }

    for cred_type, info in patterns.items():
        match = re.search(info["pattern"], content, re.IGNORECASE)
        if match:
            credentials.append({
                "file": filename,
                "type": cred_type,
                "value": match.group(1) if len(match.groups()) > 0 else match.group(0),
                "severity": info["severity"],
                "recommendation": info["recommendation"]
            })

    return credentials

def scan_for_security_issues(content, filename):
    """Scan config content for security issues."""
    issues = []

    # Check for exposed management panels
    if 'panel' in filename.lower() and ('panel.' in filename or 'admin' in filename.lower()):
        # Check if it listens on public IP
        if re.search(r'listen\s+(?:0\.0\.0\.0|[\d.]+(?:\s*,\s*\d+)+)\s+([0-9]+)', content):
            port = re.search(r'listen\s+(?:0\.0\.0\.0|[\d.]+(?:\s*,\s*\d+)+)\s+([0-9]+)', content)
            if port:
                issues.append({
                    "file": filename,
                    "issue": "Panel may be exposed to public if not properly firewalled",
                    "severity": "medium",
                    "recommendation": "Ensure management panel is only accessible via internal network or admin portal"
                })

    # Check for weak SSL protocols
    if 'ssl_protocols' in content:
        weak_protocols = re.findall(r'(?:SSL[_-]?PROTOCOLS|ssl_protocols)\s*[=:]\s*(.*)', content, re.DOTALL)
        if weak_protocols:
            protocol_str = ', '.join(weak_protocols[0].split())
            if 'TLSv1.0' in protocol_str or 'TLSv1.1' in protocol_str:
                issues.append({
                    "file": filename,
                    "issue": "Weak SSL/TLS protocols allowed (TLSv1.0, TLSv1.1)",
                    "severity": "high",
                    "recommendation": "Remove weak protocols, use only TLSv1.2 and TLSv1.3"
                })

    # Check for insecure ciphers
    if 'ssl_ciphers' in content:
        cipher_str = re.search(r'ssl_ciphers\s*[=:]\s*(.+);', content)
        if cipher_str:
            ciphers = cipher_str.group(1).upper()
            weak_ciphers = ['NULL', 'EXPORT', 'DES', 'RC4', 'MD5', 'RC2']
            for weak in weak_ciphers:
                if weak in ciphers:
                    issues.append({
                        "file": filename,
                        "issue": f"Weak cipher suite allowed: {weak}",
                        "severity": "high",
                        "recommendation": "Remove weak cipher from ssl_ciphers directive"
                    })
                    break

    # Check for directory listing
    if re.search(r'(?:DirectoryIndex|directory_listing|autoindex)\s*;\s*', content):
        issues.append({
            "file": filename,
            "issue": "Directory listing may be enabled",
            "severity": "high",
            "recommendation": "Set 'autoindex off;' in nginx config"
        })

    # Check for HTTP access to admin panels without HTTPS redirect
    if 'server {' in content and 'listen 80' in content:
        server_blocks = content.split('server {')
        if len(server_blocks) > 1:
            block_content = server_blocks[1]
            if 'admin' in block_content.lower() and 'return 301' not in block_content:
                issues.append({
                    "file": filename,
                    "issue": "Admin panel accessible via HTTP without redirect to HTTPS",
                    "severity": "critical",
                    "recommendation": "Add HTTP to HTTPS redirect in all server blocks"
                })

    # Check for exposed sensitive data
    sensitive_patterns = [
        (r'(?:\/?(?:home|var)[^/]*[\/]?(?:\.env|\.env\.example|\.env\.sample))', 'Environment file exposed', 'medium'),
        (r'(?:\/?(?:wwwroot|htdocs)[\/]?[a-zA-Z0-9_-]+(?:[\/](?:\.git|\.svn))?)', 'Git/SVN repository exposed', 'high'),
        (r'(?:/(?:\.git|\.svn)/)?$', 'Git/SVN repository potentially exposed', 'high'),
    ]

    for pattern, issue_desc, severity in sensitive_patterns:
        if re.search(pattern, filename):
            issues.append({
                "file": filename,
                "issue": issue_desc,
                "severity": severity,
                "recommendation": "Remove from public web root or set proper file permissions (644)"
            })

    return issues

def calculate_ssl_status(expiry_date_str):
    """Calculate SSL certificate expiry status."""
    try:
        expiry_date = datetime.strptime(expiry_date_str, '%Y-%m-%d').date()
    except:
        return {"status": "unknown", "days_remaining": None}

    expiry_days = (expiry_date - CURRENT_DATE).days

    if expiry_days < 0:
        return {"status": "expired", "days_remaining": expiry_days}
    elif expiry_days <= DAYS_BEFORE_CRITICAL:
        return {"status": "critical", "days_remaining": expiry_days}
    elif expiry_days <= DAYS_BEFORE_WARNING:
        return {"status": "warning", "days_remaining": expiry_days}
    else:
        return {"status": "ok", "days_remaining": expiry_days}

def main():
    audit_results = {
        "audit_metadata": {
            "timestamp": CURRENT_DATE.isoformat() + "Z",
            "workspace_path": WORKSPACE_ROOT,
            "auditor": "openclaw"
        },
        "hosted_sites": [],
        "ssl_status": [],
        "pending_changes": {
            "config_files": []
        },
        "security_issues": {
            "hardcoded_credentials": [],
            "config_issues": [],
            "sensitive_files": []
        },
        "recommendations": []
    }

    # Load site.json
    site_data = load_json_file(os.path.join(WORKSPACE_ROOT, 'www/server/panel/data/site.json'))

    if site_data:
        for site in site_data:
            site_info = {
                "name": site.get('name', f"Site {site.get('id', 'unknown')}"),
                "id": site.get('id'),
                "status": site.get('status', 'unknown'),
                "document_root": site.get('path', '/unknown'),
                "ssl": {
                    "enabled": site.get('ssl', {}).get('status', False),
                    "type": site.get('ssl', {}).get('type', 'none'),
                    "expiry": site.get('ssl', {}).get('expiry', 'unknown')
                },
                "php_version": site.get('php_version', 'unknown'),
                "backup": site.get('backup', 'unknown'),
                "created_at": site.get('addtime', 'unknown'),
                "status": "active" if site.get('status') == '1' else "inactive"
            }
            audit_results["hosted_sites"].append(site_info)

    # Calculate SSL status for each site
    for site in audit_results["hosted_sites"]:
        ssl = site.get("ssl", {})
        if ssl.get("enabled"):
            expiry_date = ssl.get("expiry")
            ssl_status = calculate_ssl_status(expiry_date)
            site["ssl"]["status"] = ssl_status["status"]
            site["ssl"]["days_until_expiry"] = ssl_status["days_remaining"]

            audit_results["ssl_status"].append({
                "site_name": site["name"],
                "expiry_date": expiry_date,
                "days_remaining": ssl_status["days_remaining"],
                "status": ssl_status["status"]
            })

    # Find .new config files and analyze differences
    for new_file in os.listdir(WORKSPACE_ROOT):
        if new_file.endswith('.new'):
            new_path = os.path.join(WORKSPACE_ROOT, new_file)
            base_name = new_file[:-4]  # Remove .new extension

            new_content = None
            diff_info = None

            # Check if corresponding .conf file exists
            conf_path = new_path.replace('.new', '')
            if os.path.exists(conf_path):
                with open(new_path, 'r') as f:
                    new_content = f.read()
                with open(conf_path, 'r') as f:
                    old_content = f.read()
                diff_info = find_diff_sections(old_content, new_content)
            else:
                # New config file
                with open(new_path, 'r') as f:
                    new_content = f.read()
                diff_info = [{"type": "new_file", "content": "New configuration", "summary": f"{base_name} created as new file"}]

            # Identify config type
            config_type = "unknown"
            if 'vhost/nginx' in new_path:
                config_type = "nginx"
            elif 'vhost/rewrite' in new_path:
                config_type = "rewrite"
            elif 'vhost/nginx/extension' in new_path:
                config_type = "extension"
            elif '.moltbot/' in new_path or '/moltbot/' in new_path:
                config_type = "application_config"

            # Site name for nginx configs
            site_name = "Unknown"
            if config_type in ["nginx", "rewrite", "extension"]:
                site_name = new_file.replace('.new', '').split('/')[0]

            # Generate summary
            if diff_info:
                summary_parts = []
                for change in diff_info:
                    summary_parts.append(f"{change.get('type', 'change')}")
                summary = "; ".join(summary_parts) if len(summary_parts) > 1 else summary_parts[0]
            else:
                summary = "No specific changes detected"

            audit_results["pending_changes"]["config_files"].append({
                "file": new_path,
                "base_name": base_name,
                "site_name": site_name,
                "config_type": config_type,
                "changes": diff_info if diff_info and len(diff_info) > 0 else {"summary": summary},
                "summary": summary
            })

    # Scan .new files for security issues
    for new_file in os.listdir(WORKSPACE_ROOT):
        if new_file.endswith('.new'):
            new_path = os.path.join(WORKSPACE_ROOT, new_file)
            security_issues = scan_for_credentials(new_file, new_file)

            # Check for specific patterns in the file content
            with open(new_path, 'r') as f:
                content = f.read()

            # Check for webhook secret placeholders
            if 'wh_sec_EXAMPLE' in content or 'EXAMPLE_REPLACE' in content or 'placeholder' in content.lower():
                if "webhook_secret" not in [c['type'] for c in security_issues]:
                    security_issues.append({
                        "file": new_file,
                        "type": "placeholder_secret",
                        "value": "PLACEHOLDER_SECRET",
                        "severity": "medium",
                        "recommendation": "Replace placeholder with real secret key"
                    })

            audit_results["security_issues"]["hardcoded_credentials"].extend(security_issues)

    # Scan all config files for issues
    for root, dirs, files in os.walk(WORKSPACE_ROOT):
        # Skip .new files and .openclaw directory
        files = [f for f in files if not f.endswith('.new') and f not in ['.openclaw', '.gitignore', 'SKILL.md', 'audit_results.py']]

        for file in files:
            file_path = os.path.join(root, file)

            # Skip directories
            if os.path.isdir(file_path):
                continue

            issues = scan_for_security_issues(file, file_path)

            for issue in issues:
                issue['file'] = file_path  # Ensure full path
                audit_results["security_issues"]["config_issues"].append(issue)

    # Generate recommendations
    recommendations = []

    # SSL expiry warnings
    for ssl in audit_results["ssl_status"]:
        if ssl["status"] == "critical":
            recommendations.append({
                "priority": "critical",
                "category": "ssl",
                "description": f"SSL certificate for {ssl['site_name']} expires in {ssl['days_remaining']} days",
                "affected": [ssl['site_name']],
                "action": "Renew SSL certificate immediately"
            })
        elif ssl["status"] == "warning":
            recommendations.append({
                "priority": "medium",
                "category": "ssl",
                "description": f"SSL certificate for {ssl['site_name']} expires in {ssl['days_remaining']} days",
                "affected": [ssl['site_name']],
                "action": "Schedule SSL certificate renewal within 2 weeks"
            })

    # Security issues
    for issue in audit_results["security_issues"]["hardcoded_credentials"]:
        recommendations.append({
            "priority": issue["severity"],
            "category": "security",
            "description": issue["recommendation"],
            "affected": [os.path.basename(issue['file'])],
            "action": f"Remove {issue['type']} from config file"
        })

    # Check for crypto keys
    for issue in audit_results["security_issues"]["hardcoded_credentials"]:
        if 'API_KEY' in issue['value'] or 'GCM' in issue['value'] or 'SHA256' in issue['value']:
            recommendations.append({
                "priority": "critical",
                "category": "security",
                "description": "Potential crypto key found in plaintext - DO NOT commit to version control",
                "affected": [os.path.basename(issue['file'])],
                "action": "Remove and use secure key management service"
            })

    # Pending config changes
    if audit_results["pending_changes"]["config_files"]:
        recommendations.append({
            "priority": "medium",
            "category": "config",
            "description": f"{len(audit_results['pending_changes']['config_files'])} pending configuration changes detected",
            "affected": [cf["base_name"] for cf in audit_results["pending_changes"]["config_files"]],
            "action": "Review and apply pending configuration changes"
        })

    audit_results["recommendations"] = recommendations

    # Write audit results
    output_path = os.path.join(WORKSPACE_ROOT, 'server_audit.json')
    with open(output_path, 'w') as f:
        json.dump(audit_results, f, indent=2)

    print(f"Audit complete. Results saved to {output_path}")
    print(f"\nSummary:")
    print(f"  Sites: {len(audit_results['hosted_sites'])}")
    print(f"  SSL Certificates: {len(audit_results['ssl_status'])}")
    print(f"  Pending Changes: {len(audit_results['pending_changes']['config_files'])}")
    print(f"  Critical Security Issues: {len([r for r in audit_results['recommendations'] if r['priority'] == 'critical'])}")
    print(f"  High Priority Issues: {len([r for r in audit_results['recommendations'] if r['priority'] == 'high'])}")

if __name__ == "__main__":
    main()
