import json
import os
from datetime import datetime, date
import re

# Configuration
CURRENT_DATE = date(2026, 8, 19)  # Current date for SSL expiry calculation
DAYS_BEFORE_CRITICAL = 30
DAYS_BEFORE_WARNING = 60
WORKSPACE_ROOT = "."

def load_json_file(path):
    """Load a JSON file and return its contents."""
    try:
        with open(path, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        return None
    except json.JSONDecodeError:
        return None

def calculate_ssl_status(expiry_date_str):
    """Calculate SSL certificate expiry status."""
    try:
        expiry_date = datetime.strptime(expiry_date_str, '%Y-%m-%d').date()
    except:
        return {"status": "unknown", "days_remaining": None}

    expiry_days = (expiry_date - CURRENT_DATE).days

    if expiry_days < 0:
        return {"status": "expired", "days_remaining": expiry_days}
    elif expiry_days <= DAYS_BEFORE_CRITICAL:
        return {"status": "critical", "days_remaining": expiry_days}
    elif expiry_days <= DAYS_BEFORE_WARNING:
        return {"status": "warning", "days_remaining": expiry_days}
    else:
        return {"status": "ok", "days_remaining": expiry_days}

def find_matching_config(base_path):
    """Find the matching current config file for a .new file."""
    # Look in the same directory for a non-.new version
    base_dir = os.path.dirname(base_path)
    base_name = os.path.basename(base_path)

    # Remove .new if present
    if base_name.endswith('.new'):
        base_name_no_ext = base_name[:-4]
    else:
        base_name_no_ext = base_name

    # Try to find matching file in same dir
    candidate = os.path.join(base_dir, base_name_no_ext)
    if os.path.exists(candidate) and not candidate.endswith('.new'):
        return candidate

    return None

def compare_json_configs(old_data, new_data):
    """Compare two JSON configs and return structured differences."""
    if old_data is None:
        return [{"type": "new_file", "summary": "New configuration file"}]

    differences = []

    # Check for new keys
    for key in new_data:
        if key not in old_data:
            differences.append({
                "type": "added",
                "key": key,
                "old_value": None,
                "new_value": new_data[key],
                "summary": f"New key '{key}' added with value {str(new_data[key])[:50]}..."
            })
        else:
            old_val = old_data[key]
            new_val = new_data[key]

            if isinstance(old_val, dict) and isinstance(new_val, dict):
                for sub_key in new_val:
                    if sub_key not in old_val:
                        differences.append({
                            "type": "added_nested",
                            "key": f"{key}.{sub_key}",
                            "old_value": None,
                            "new_value": new_val[sub_key],
                            "summary": f"New nested key '{key}.{sub_key}' added"
                        })
                    elif old_val[sub_key] != new_val[sub_key]:
                        differences.append({
                            "type": "changed",
                            "key": f"{key}.{sub_key}",
                            "old_value": old_val[sub_key],
                            "new_value": new_val[sub_key],
                            "summary": f"Changed: {old_val[sub_key]} -> {new_val[sub_key]}"
                        })

