    if os.path.exists(candidate) and not candidate.endswith('.new'):
        return candidate

    return None

def compare_json_configs(old_data, new_data):
    """Compare two JSON configs and return structured differences."""
    if old_data is None:
        return [{"type": "new_file", "summary": "New configuration file"}]

    differences = []

    # Check for new keys
    for key in new_data:
        if key not in old_data:
            differences.append({
                "type": "added",
                "key": key,
                "old_value": None,
                "new_value": new_data[key],
                "summary": f"New key '{key}' added with value {str(new_data[key])[:50]}..."
            })
        else:
            old_val = old_data[key]
            new_val = new_data[key]

            if isinstance(old_val, dict) and isinstance(new_val, dict):
                for sub_key in new_val:
                    if sub_key not in old_val:
                        differences.append({
                            "type": "added_nested",
                            "key": f"{key}.{sub_key}",
                            "old_value": None,
                            "new_value": new_val[sub_key],
                            "summary": f"New nested key '{key}.{sub_key}' added"
                        })
                    elif old_val[sub_key] != new_val[sub_key]:
                        differences.append({
                            "type": "changed",
                            "key": f"{key}.{sub_key}",
                            "old_value": old_val[sub_key],
                            "new_value": new_val[sub_key],
                            "summary": f"Changed: {old_val[sub_key]} -> {new_val[sub_key]}"
                        })

    # Check for removed keys
    for key in old_data:
        if key not in new_data:
            differences.append({
                "type": "removed",
                "key": key,
                "old_value": old_data[key],
                "new_value": None,
                "summary": f"Key '{key}' has been removed"
            })

    return differences

def scan_for_credentials(content, filename):
    """Scan config content for sensitive credentials."""
    credentials = []

    # Patterns for different types of secrets
    patterns = {
        "webhook_secret": {
            "pattern": r'"webhook":\s*\{[^}]*"secret"\s*:[\s]*"([^"]+)"',
            "severity": "critical",
            "recommendation": "Webhook secret should not be in config - remove and use environment variable"
        },
        "telegram_token": {
            "pattern": r'"plugins":\s*\{[^}]*"telegram":\s*\{[^}]*"token"\s*:[\s]*"([^"]+)"',
            "severity": "high",
            "recommendation": "Move Telegram token to environment variables or secret manager"
        }
    }

    for cred_type, info in patterns.items():
        match = re.search(info["pattern"], content)
        if match:
            credentials.append({
                "file": filename,
                "type": cred_type,
                "value": match.group(1),
                "severity": info["severity"],
                "recommendation": info["recommendation"]
            })

    return credentials

def get_api_key_issues(content, filename):
    """Check for remote gateway security issues."""
    issues = []

    # Check if remote gateway is enabled
    if 'gateway' in content and '"remote"' in content:
        enabled_match = re.search(r'"remote":\s*\{[^}]*"enabled":\s*([^\s,]+)', content, re.DOTALL)
        if enabled_match:
            is_enabled = enabled_match.group(1).lower()
            if is_enabled == "true":
                issues.append({
                    "file": filename,
                    "issue": "Remote gateway is currently enabled",
                    "severity": "medium",
                    "recommendation": "Verify remote access is properly secured before keeping enabled"
                })

    return issues

def generate_summary(diff):
    """Generate a human-readable summary from diff data."""
    if not diff:
        return "No changes detected"

    changes = diff if isinstance(diff, list) else [diff]

    summary_parts = []
    for change in changes:
        summary_parts.append(f"{change['type']}: {change['key']}" if 'key' in change else change['type'])

    return "; ".join(summary_parts) if len(summary_parts) > 1 else summary_parts[0]

