            }
            audit_results["hosted_sites"].append(site_info)

            # Add to SSL status
            ssl = site_info["ssl"]
            if ssl["enabled"]:
                expiry_status = calculate_ssl_status(ssl.get("expiry"))
                site_info["ssl"]["status"] = expiry_status["status"]
                site_info["ssl"]["days_until_expiry"] = expiry_status["days_remaining"]

                audit_results["ssl_status"].append({
                    "site_name": site_info["name"],
                    "site_id": site_info["id"],
                    "expiry_date": ssl.get("expiry"),
                    "days_remaining": expiry_status["days_remaining"],
                    "status": expiry_status["status"]
                })

    # 2. Scan all .new files in workspace recursively
    for root, dirs, files in os.walk(WORKSPACE_ROOT):
        for filename in files:
            if filename.endswith('.new'):
                new_path = os.path.join(root, filename)
                base_path = new_path

                # Find matching current config
                matching_config = find_matching_config(base_path)

                if matching_config and os.path.exists(matching_config):
                    # Has current version to compare against
                    with open(new_path, 'r') as f:
                        new_content = f.read()
                    with open(matching_config, 'r') as f:
                        old_content = f.read()

                    # Determine config type
                    config_type = "unknown"
                    if filename.endswith('.json'):
                        config_type = "json"
                    elif '/nginx/' in base_path:
                        if '/vhost/' in base_path or 'nginx.conf' in base_path:
                            config_type = "nginx"
                        elif '/extension/' in base_path:
                            config_type = "extension"
                        else:
                            config_type = "nginx_other"
                    elif '/panel/' in base_path or '/data/' in base_path:
                        config_type = "site_panel"
                    elif '.php' in filename:
                        config_type = "php"

                    # Parse JSON configs
                    new_data = None
                    old_data = None

                    if config_type == "json":
                        try:
                            new_data = json.loads(new_content)
                            old_data = json.loads(old_content)
                        except json.JSONDecodeError:
                            pass

                    # Compare
                    if new_data and old_data:
                        differences = compare_json_configs(old_data, new_data)
                    else:
                        differences = []

                    audit_results["pending_changes"]["config_files"].append({
                        "file": new_path,
                        "base_name": filename[:-4],  # Remove .new
                        "config_type": config_type,
                        "diff": {
                            "type": "config_changes",
                            "changes": differences
                        }
                    })
                else:
                    # Brand new config - no matching current version
                    with open(new_path, 'r') as f:
                        content = f.read()

                    config_type = "unknown"
                    if filename.endswith('.json'):
                        config_type = "json"
                    elif '/nginx/' in base_path:
                        if '/vhost/' in base_path:
                            config_type = "nginx"
                        else:
                            config_type = "nginx_other"

                    audit_results["pending_changes"]["config_files"].append({
                        "file": new_path,
                        "base_name": filename[:-4],
                        "config_type": config_type,
                        "diff": {
                            "type": "new_file"
                        }
                    })

    # 3. Scan .new files for security issues
    for root, dirs, files in os.walk(WORKSPACE_ROOT):
        for filename in files:
            if filename.endswith('.new'):
                new_path = os.path.join(root, filename)

                with open(new_path, 'r') as f:
                    content = f.read()

                # Scan for credentials
                creds = scan_for_credentials(content, filename)
                audit_results["security_issues"]["hardcoded_credentials"].extend(creds)

                # Check for config issues
                issues = get_api_key_issues(content, filename)
                audit_results["security_issues"]["config_issues"].extend(issues)

    # 4. Generate recommendations from findings
    recommendations = []

    # SSL recommendations
    for ssl in audit_results["ssl_status"]:
        status = ssl["status"]
        days = ssl["days_remaining"]

        if status == "expired":
            recommendations.append({
                "priority": "critical",
                "category": "ssl",
                "description": f"SSL certificate for '{ssl['site_name']}' has expired ({days} days ago)",
                "affected": [ssl['site_name']],
                "action": "IMMEDIATE: Renew SSL certificate for this site"
            })
        elif status == "critical":
            recommendations.append({
                "priority": "critical",
                "category": "ssl",
                "description": f"SSL certificate for '{ssl['site_name']}' expires in {days} days",
                "affected": [ssl['site_name']],
                "action": "CRITICAL: Renew SSL certificate within 24 hours"
            })
        elif status == "warning":
            recommendations.append({
                "priority": "medium",
                "category": "ssl",
                "description": f"SSL certificate for '{ssl['site_name']}' expires in {days} days",
                "affected": [ssl['site_name']],
                "action": "Schedule SSL certificate renewal within 14 days"
            })

