    for cred in audit_results["security_issues"]["hardcoded_credentials"]:
        recommendations.append({
            "priority": cred["severity"],
            "category": "security",
            "description": f"Exposed {cred['type']} in {os.path.basename(cred['file'])}: {cred['value'][:15]}...",
            "affected": [os.path.basename(cred['file'])],
            "action": f"IMMEDIATE: Remove {cred['type']} from config file"
        })

    # Config change recommendations
    if audit_results["pending_changes"]["config_files"]:
        for fc in audit_results["pending_changes"]["config_files"]:
            rec_priority = "medium"
            if fc['diff']['type'] == 'new_file':
                rec_priority = "low"

            recommendations.append({
                "priority": rec_priority,
                "category": "config",
                "description": f"Pending changes to {fc['base_name']}: {generate_summary(fc['diff'].get('changes', []))}",
                "affected": [fc['base_name']],
                "action": "Review config changes and apply if needed"
            })

    audit_results["recommendations"] = recommendations

    # Write audit results
    output_path = os.path.join(WORKSPACE_ROOT, 'server_audit.json')
    with open(output_path, 'w') as f:
        json.dump(audit_results, f, indent=2)

